    memCache, err := cache.NewCache(cache.MemoryCache, "", "", 0)
    if err != nil {
        fmt.Println("Error creating cache:", err)
        return
    }

    memCache.Set("key1", "value1")
    value, _ := memCache.Get("key1")
    fmt.Println("Memory Cache:", value)

    // Example for Redis cache
    redisCache, err := cache.NewCache(cache.RedisCache, "localhost:6379", "", 0)
    if err != nil {
        fmt.Println("Error creating cache:", err)
        return
    }

    redisCache.Set("key2", "value2")
    value, _ = redisCache.Get("key2")
    fmt.Println("Redis Cache:", value)
}
```

