To create a Go constructor for a `Server` that accepts optional parameters such as host, port, timeout, and TLS configuration, we can use the functional options pattern. This pattern allows us to provide default values and override them with optional parameters in a clean and flexible way. Here's how you can implement it:

```go
package server

import (
	"crypto/tls"
	"time"
)

// Server represents a configurable server.
type Server struct {
	host    string
	port    int
	timeout time.Duration
	tlsConfig *tls.Config
}

// Option defines a function type for setting optional parameters.
type Option func(*Server)

// NewServer creates a new Server with the given options.
func NewServer(opts ...Option) *Server {
	// Set default values
	s := &Server{
		host:    "localhost",
		port:    8080,
		timeout: 30 * time.Second,
		tlsConfig: nil,
	}

	// Apply options
	for _, opt := range opts {
		opt(s)
	}

	return s
}

// WithHost sets the host for the server.
func WithHost(host string) Option {
	return func(s *Server) {
		s.host = host
	}
}

// WithPort sets the port for the server.
func WithPort(port int) Option {
	return func(s *Server) {
		s.port = port
	}
}

// WithTimeout sets the timeout for the server.
func WithTimeout(timeout time.Duration) Option {
	return func(s *Server) {
		s.timeout = timeout
	}
}

// WithTLSConfig sets the TLS configuration for the server.
func WithTLSConfig(tlsConfig *tls.Config) Option {
	return func(s *Server) {
		s.tlsConfig = tlsConfig
	}
}
```

