		return fmt.Errorf("fetching URL: %w", err)
	}

	fmt.Println("Response:", response)
	return nil
}

func fetchWithTimeout(url string, timeout time.Duration) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("performing request: %w", err)
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("reading response body: %w", err)
	}

	return string(body), nil
}
```

### Explanation:

1. **Context with Timeout**: We use `context.WithTimeout` to create a context that automatically cancels the request if it takes longer than the specified timeout (5 seconds in this case).

2. **HTTP Request**: We create an HTTP GET request using `http.NewRequestWithContext`, which associates the context with the request.

3. **HTTP Client**: We use the default `http.Client` to perform the request. The context ensures that if the request takes longer than the timeout, it will be canceled.

4. **Error Handling**: Errors are wrapped with context using `fmt.Errorf`, providing clarity on where the error occurred.

5. **Main Function**: The `main` function is kept clean, with a single call to `app.Run()`, adhering to the project structure guidelines.

