	"fmt"
	"log"
)

// ProcessItems reads integers from the input channel, processes each item,
// and logs the result. It stops processing when the channel is closed.
func ProcessItems(input <-chan int) {
	for item := range input {
		result, err := processItem(item)
		if err != nil {
			log.Printf("process item: %v", err)
			continue
		}
