package user_test

import (
    "testing"
    "errors"
    "github.com/yourproject/internal/user"
)

func TestUserValidation(t *testing.T) {
    tests := []struct {
        name     string
        user     user.User
        wantErr  bool
        errMsg   string
    }{
        {
            name: "valid user",
            user: user.User{
                Name:  "John Doe",
                Email: "john.doe@example.com",
                Age:   30,
            },
            wantErr: false,
        },
        {
            name: "missing name",
            user: user.User{
                Email: "john.doe@example.com",
                Age:   30,
            },
            wantErr: true,
            errMsg:  "name is required",
        },
        {
            name: "invalid email",
            user: user.User{
                Name:  "John Doe",
                Email: "invalid-email",
                Age:   30,
            },
            wantErr: true,
            errMsg:  "invalid email format",
        },
        {
            name: "age below minimum",
            user: user.User{
                Name:  "John Doe",
                Email: "john.doe@example.com",
                Age:   15,
            },
            wantErr: true,
            errMsg:  "age must be at least 18",
        },
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            err := user.Validate(tt.user)
            if (err != nil) != tt.wantErr {
                t.Fatalf("expected error: %v, got: %v", tt.wantErr, err)
