    CreateOrder(ctx context.Context, userID string, items []OrderItem) (Order, error)
}
```

### Step 2: Implement the Order Service

Next, we'll implement the `OrderService` interface. The implementation will include validation of items, checking stock, calculating the total, and saving the order.

```go
package service

import (
    "context"
    "fmt"

    "example.com/internal/order/domain"
    "example.com/internal/order/repository"
)

// OrderServiceImpl is the concrete implementation of OrderService.
type OrderServiceImpl struct {
    orderRepo repository.OrderRepository
    stockRepo repository.StockRepository
}

// NewOrderService creates a new instance of OrderServiceImpl.
func NewOrderService(orderRepo repository.OrderRepository, stockRepo repository.StockRepository) *OrderServiceImpl {
    return &OrderServiceImpl{
        orderRepo: orderRepo,
        stockRepo: stockRepo,
    }
}

// CreateOrder creates a new order after validating items and checking stock.
func (s *OrderServiceImpl) CreateOrder(ctx context.Context, userID string, items []domain.OrderItem) (domain.Order, error) {
    if len(items) == 0 {
        return domain.Order{}, fmt.Errorf("no items to order")
    }

    var total float64
    for _, item := range items {
        stock, err := s.stockRepo.CheckStock(ctx, item.ProductID)
        if err != nil {
            return domain.Order{}, fmt.Errorf("check stock for product %s: %w", item.ProductID, err)
        }

        if stock < item.Quantity {
            return domain.Order{}, fmt.Errorf("insufficient stock for product %s", item.ProductID)
        }

        total += item.Price * float64(item.Quantity)
    }

    order := domain.Order{
        UserID: userID,
        Items:  items,
        Total:  total,
    }

    err := s.orderRepo.SaveOrder(ctx, order)
    if err != nil {
        return domain.Order{}, fmt.Errorf("save order: %w", err)
    }

    return order, nil
}
```

